int[] previousSmaller(int[] nums) {
    int[] ans = new int[nums.length];
    Arrays.fill(ans, -1);
    Deque<Integer> stack = new ArrayDeque<>();   // increasing from bottom to top
    for (int i = 0; i < nums.length; i++) {
        while (!stack.isEmpty() && stack.peek() >= nums[i]) {
            stack.pop();                         // nums[i] hides it from everyone to the right
        }
        if (!stack.isEmpty()) ans[i] = stack.peek();
        stack.push(nums[i]);
    }
    return ans;
}

